from datetime import datetime, timezone
import json

def clean(value):
    if value is None or value == "":
        return "Not available"

    value = str(value).strip()
    value = value.replace("|", r"\|")
    value = value.replace("\r", " ").replace("\n", " ")
    return value

def code(value):
    text = clean(value)

    if text == "Not available":
        return text  

    if "`" in text:
        return f"`` {text} ``"

    return f"`{text}`"


def process_name(image):
    if not image:
        return "Unknown"

    return str(image).replace("\\", "/").rstrip("/").split("/")[-1]


def format_timestamp(event):
    timestamp = event.get("UtcTime") or event.get("_time")

    if not timestamp:
        return "Unknown"

    return clean(timestamp)


def format_activity(event_id, event):

    if event_id == "1":
        evidence = (
            f"Created: {code(event.get('Image'))}; "
            f"Command: {code(event.get('CommandLine'))}"
        )
        actor = process_name(event.get("ParentImage"))

    elif event_id == "3":
        destination = (
            f"{clean(event.get('DestinationIp'))}:"
            f"{clean(event.get('DestinationPort'))}"
        )
        evidence = f"Destination: {code(destination)} ({clean(event.get('Protocol'))})"
        actor = process_name(event.get("Image"))

    elif event_id == "11":
        evidence = f"Created file: {code(event.get('TargetFilename'))}"
        actor = process_name(event.get("Image"))

    elif event_id == "13":
        evidence = (
            f"Modified: {code(event.get('TargetObject'))}; "
            f"Data: {code(event.get('Details'))}"
        )
        actor = process_name(event.get("Image"))

    elif event_id == "22":
        evidence = (
            f"Queried: {code(event.get('QueryName'))}; "
            f"Results: {code(event.get('QueryResults'))}; "
            f"Status: {clean(event.get('QueryStatus'))}"
        )
        actor = process_name(event.get("Image"))

    else:
        return None

    return {
        "time": format_timestamp(event),
        "event_id": event_id,
        "activity": {
            "1": "Child process created",
            "3": "Network connection",
            "11": "File created",
            "13": "Registry modified",
            "22": "DNS query"
        }[event_id],
        "process": actor,
        "evidence": evidence
    }




def build_process_report(splunk_response, root_process_guid):

    results = splunk_response

    if not isinstance(results, list):
        raise ValueError("Splunk results must be a list")

    if not root_process_guid:
        raise ValueError("Root ProcessGuid is required")

    root_process_guid = root_process_guid.strip().lower()

    summary = {
        "child_processes": 0,
        "network_connections": 0,
        "files_created": 0,
        "registry_modifications": 0,
        "dns_queries": 0
    }

    activity_rows = []

    for event in results:

        event_id = str(event.get("EventCode", "")).strip()

        process_guid = str(
            event.get("ProcessGuid", "")
        ).strip().lower()

        parent_guid = str(
            event.get("ParentProcessGuid", "")
        ).strip().lower()


        if event_id == "1":
            if parent_guid != root_process_guid:
                continue

            summary["child_processes"] += 1

        elif event_id == "3":
            if process_guid != root_process_guid:
                continue

            summary["network_connections"] += 1

        elif event_id == "11":
            if process_guid != root_process_guid:
                continue

            summary["files_created"] += 1

        elif event_id == "13":
            if process_guid != root_process_guid:
                continue

            summary["registry_modifications"] += 1

        elif event_id == "22":
            if process_guid != root_process_guid:
                continue

            summary["dns_queries"] += 1

        else:
            continue

        activity = format_activity(event_id, event)

        if activity:
            activity_rows.append(activity)


    activity_rows.sort(key=lambda row: row["time"])

    summary_markdown = """## 7. Process Activity Summary

| Activity | Count |
|---|---:|
"""

    summary_labels = {
        "child_processes": "Child processes created",
        "network_connections": "Network connections",
        "files_created": "Files created",
        "registry_modifications": "Registry modifications",
        "dns_queries": "DNS queries"
    }

    for key, label in summary_labels.items():
        summary_markdown += (
            f"| {label} | {summary[key]} |\n"
        )


    activity_markdown = """## 8. Correlated Process Activity

| Time (UTC) | Activity | Process | Evidence |
|---|---|---|---|
"""

    if activity_rows:

        for row in activity_rows:
            activity_markdown += (
                f"| {row['time']} "
                f"| {row['activity']} "
                f"| `{clean(row['process'])}` "
                f"| {row['evidence']} |\n"
            )

    else:
        activity_markdown += (
            "| - | No matching activity | - | "
            "No matching events returned |\n"
        )

    return {
        "summary": summary,
        "activity_rows": activity_rows,
        "markdown": summary_markdown + "\n" + activity_markdown
    }


raw = r"""$splunk.body"""

data = [json.loads(line) for line in raw.splitlines() if line.strip()]
events = [row["result"] for row in data if "result" in row]

report = build_process_report(
    splunk_response=events,
    root_process_guid="$exec.all_fields.full_log.win.eventdata.processGuid",
)

print(report["markdown"])

import ast
import re
import json
from datetime import datetime, timezone


def parse(raw):
    s = re.sub(r'\b(U|u)ndefined\b', 'None', str(raw))
    return ast.literal_eval(s)

wazuh = parse(r"""{{ $exec.all_fields }}""")
